;; jp_0513_rst38()
;;  Description:
;;    RST $0038 handler.
;;    The first part uses vsync signal to develop clock references.
;;      ds3_92A0_frame_cts[0]: 60Hz (base rate)
;;      ds3_92A0_frame_cts[1]:  2Hz (div 32)
;;      ds3_92A0_frame_cts[2]:  4Hz (div 16)
;;    The counters are not reset in the course of the game operation.
;;    For efficiency, bit masking is used instead of division so the real base
;;    period is 64 which is close enough to 60Hz.
;;    Note: frame_cts[2] is used as baserate to 4 Game Timers in CPU0:f_1DD2
;;   (rescaled to develop a 2Hz clock)
;; IN:
;;  ...
;; OUT:
;;  ...
jp_0513_rst38:
0513: AF                      xor  a                
0514: 32 21 68                ld   ($6821),a        ; {ld (_sfr_6821),a} 0 ...CPU-sub1 IRQ acknowledge/enable
0517: 3A 04 68                ld   a,($6804)        ; {ld a,(_sfr_dsw5)} DSWA: freeze video
051A: E6 02                   and  $02              ; freeze_ctrl_dsw (6j)
051C: CA 75 05                jp   z,$0575          ; -> l_0575  if paused, goto 0575 // done

;; frame_cntr++
051F: 3A A0 92                ld   a,($92A0)        ; {ld a,(ds3_92A0_frame_cts + 0)}
0522: 3C                      inc  a                
0523: 32 A0 92                ld   ($92A0),a        ; {ld (ds3_92A0_frame_cts + 0),a} +=1

;; L==t[1], H==t[2]
0526: 2A A1 92                ld   hl,($92A1)       ; {ld hl,(ds3_92A0_frame_cts + 1)} load 16-bits

;; if ( cnt % 20 == 1 ) ... update 4Hz (H) only
0529: E6 1F                   and  $1F              ; MOD $20
052B: 3D                      dec  a                
052C: 28 08                   jr   z,$0536          ; -> l_0536

;; else  if ( cnt % 20 == 0 ) ...
052E: 3C                      inc  a                ; restores original value and allows test for 0
052F: 20 06                   jr   nz,$0537         ; -> l_0537  A!=0 && A!=1 .... do nothing (why reload from HL?)

;; ...
;; Before incrementing 4Hz, assert that 4Hz is ODD on frame where _92A0[0] increments to 0.
0531: 7C                      ld   a,h              ; t[2] ... MSB
0532: F6 01                   or   $01              
0534: 67                      ld   h,a              

;; update both 4Hz and 2Hz
0535: 2C                      inc  l                ; t[1] = L++ ... 2Hz
l_0536:
0536: 24                      inc  h                ; t[2] = H++ ... 4Hz
l_0537:
0537: 22 A1 92                ld   ($92A1),hl       ; {ld (ds3_92A0_frame_cts + 1),hl} [1]: 32-frame ... ~2Hz timer

;; [2]: 16-frame ... ~4Hz timer
;; flag = ( num_bugs < param07 ) && ds_cpu0_task_actv[0x15]
053A: 3A C7 99                ld   a,($99C7)        ; {ld a,(ds_new_stage_parms + 0x07)} number of aliens left when continous bombing can start
053D: 5F                      ld   e,a              
053E: 3A A7 92                ld   a,($92A7)        ; {ld a,(b_bugs_actv_nbr)}
0541: BB                      cp   e                
0542: CB 10                   rl   b                ; Cy set if E > A ... shift into B ... clever.
0544: 3A 15 90                ld   a,($9015)        ; {ld a,(ds_cpu0_task_actv + 0x15)} cpu0:f_1F04 (reads fire button input)
0547: A0                      and  b                
0548: E6 01                   and  $01              ; mask off bit-0
054A: 32 AA 92                ld   ($92AA),a        ; [$92AA: flag determines continuous bombing] continuous bombing flag (set here by tasking kernel)

;; find the first ready task.. may run more than one.
054D: 0E 00                   ld   c,$00            
l_054F_while:
054F: 21 20 90                ld   hl,$9020         ; {ld hl,#ds_cpu1_task_actv}
0552: 79                      ld   a,c              
