0CFC: 86                      add  a,(hl)           
0CFD: 77                      ld   (hl),a           ; .b00 or .b02
0CFE: 2C                      inc  l                
0CFF: 7A                      ld   a,d              ; msb of mul result
0D00: 8E                      adc  a,(hl)           ; .b01 or .b03
0D01: 77                      ld   (hl),a           
